/* @lc app=leetcode id=2662 lang=kotlin */ class Solution { fun minimumCost(start: IntArray, target: IntArray, specialRoads: Array<IntArray>): Int = (listOf(start[0] to start[1]) + specialRoads.map { it[2] to it[3] }).let { pts -> LongArray(pts.size) { Long.MAX_VALUE / 4 }.also { it[0] = 0 }.let { d -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy<Pair<Long, Int>> { it.first }).also { it.add(0L to 0) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> specialRoads.indices.forEach { r -> (c + Math.abs(pts[u].first - specialRoads[r][0]) + Math.abs(pts[u].second - specialRoads[r][1]) + specialRoads[r][4]).let { nd -> if (nd < d[r + 1]) pq.add(nd to r + 1).also { d[r + 1] = nd } } } }.let { pts.indices.minOf { d[it] + Math.abs(pts[it].first - target[0]) + Math.abs(pts[it].second - target[1]) }.toInt() } } } } }